#define VM_SET_TEXT_SOUND(BANK, ADDR, MASK) 0x8B, (UBYTE)(MASK), (UBYTE)((ADDR) >> 8), (UBYTE)(ADDR), (UBYTE)(BANK)
#define VM_PRINTER_DETECT(ERROR, DELAY) 0x8C, (UBYTE)(DELAY), (UBYTE)((ERROR) >> 8), (UBYTE)(ERROR)
#define VM_PRINT_OVERLAY(ERROR, START, HEIGHT, MARGIN) 0x8D, (UBYTE)(MARGIN), (UBYTE)(HEIGHT), (UBYTE)(START), (UBYTE)((ERROR) >> 8), (UBYTE)(ERROR)
