#define VM_ACTOR_MOVE_TO_Y(IDX, ATTR) 0x91, (UBYTE)(ATTR), (UBYTE)((IDX) >> 8), (UBYTE)(IDX)
#define VM_ACTOR_MOVE_TO_XY(IDX, ATTR) 0x92, (UBYTE)(ATTR), (UBYTE)((IDX) >> 8), (UBYTE)(IDX)
#define VM_ACTOR_MOVE_TO_SET_DIR_X(IDX) 0x93, (UBYTE)((IDX) >> 8), (UBYTE)(IDX)
#define VM_ACTOR_MOVE_TO_SET_DIR_Y(IDX) 0x94, (UBYTE)((IDX) >> 8), (UBYTE)(IDX)
